//! Route table and router assembly.
//!
//! [`ROUTES`] is the single source of truth for what coolify-rs implements:
//! the router applies each entry's abilities, and
//! `tests/route_inventory.rs` checks every entry against the upstream route
//! inventory generated by `coolify-port` (method, URI, group, abilities).

pub mod misc;
pub mod projects;
pub mod teams;

use axum::Router;
use axum::http::Method;
use axum::middleware::{from_fn, from_fn_with_state};
use axum::routing::{MethodRouter, on};
use coolify_domain::Ability;

use crate::state::AppState;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Group {
    /// No authentication (`/api/health`).
    Public,
    /// Main `/api/v1` group.
    Main,
    /// `/api/v1/disable` group.
    Disable,
}

#[derive(Debug)]
pub struct RouteSpec {
    pub method: &'static str,
    /// Upstream URI (`routes/api.php` with prefixes), also the axum path.
    pub uri: &'static str,
    pub group: Group,
    /// Each inner slice is one `api.ability:` middleware (any-of); all must pass.
    pub abilities: &'static [&'static [Ability]],
}

use Ability::{Read, Write};

const R: &[&[Ability]] = &[&[Read]];
const W: &[&[Ability]] = &[&[Write]];
const NONE: &[&[Ability]] = &[];

