fn spec(method: &str, uri: &str) -> &'static RouteSpec {
    ROUTES
        .iter()
        .find(|s| s.method == method && s.uri == uri)
        .unwrap_or_else(|| panic!("route {method} {uri} missing from ROUTES"))
}

/// Builds the `/api` router.
pub fn router(state: AppState) -> Router {
    let handlers: Vec<(&str, &str, MethodRouter<AppState>)> = vec![
        ("GET", "api/health", on_get(misc::health)),
        ("GET", "api/v1/health", on_get(misc::health)),
        ("GET", "api/v1/disable", on_get(misc::post_required)),
        ("POST", "api/v1/disable", on_post(misc::disable_api)),
        ("GET", "api/v1/version", on_get(misc::version)),
        ("GET", "api/v1/teams", on_get(teams::teams)),
        ("GET", "api/v1/team", on_get(teams::current_team)),
        (
            "PATCH",
            "api/v1/team",
            on(
                axum::routing::MethodFilter::PATCH,
                teams::update_current_team,
            ),
        ),
        (
            "GET",
            "api/v1/team/members",
            on_get(teams::current_team_members),
        ),
        ("GET", "api/v1/teams/current", on_get(teams::current_team)),
        (
            "GET",
            "api/v1/teams/current/members",
            on_get(teams::current_team_members),
        ),
        ("GET", "api/v1/teams/{id}", on_get(teams::team_by_id)),
        (
            "GET",
            "api/v1/teams/{id}/members",
            on_get(teams::members_by_id),
        ),
        ("GET", "api/v1/projects", on_get(projects::list)),
        ("POST", "api/v1/projects", on_post(projects::create)),
        ("GET", "api/v1/projects/{uuid}", on_get(projects::show)),
        (
            "PATCH",
            "api/v1/projects/{uuid}",
            on(axum::routing::MethodFilter::PATCH, projects::update),
        ),
        (
            "DELETE",
            "api/v1/projects/{uuid}",
            on(axum::routing::MethodFilter::DELETE, projects::delete),
        ),
        (
            "GET",
            "api/v1/projects/{uuid}/environments",
            on_get(projects::environments),
        ),
        (
            "POST",
            "api/v1/projects/{uuid}/environments",
            on_post(projects::create_environment),
        ),
        (
            "PATCH",
            "api/v1/projects/{uuid}/environments/{environment_name_or_uuid}",
            on(
                axum::routing::MethodFilter::PATCH,
                projects::update_environment,
            ),
        ),
        (
            "DELETE",
            "api/v1/projects/{uuid}/environments/{environment_name_or_uuid}",
            on(
                axum::routing::MethodFilter::DELETE,
                projects::delete_environment,
            ),
        ),
        (
            "GET",
            "api/v1/projects/{uuid}/{environment_name_or_uuid}",
            on_get(projects::environment_details),
        ),
    ];

    // Group handlers by path so one MethodRouter serves all verbs of a path.
    let mut by_path: Vec<(&str, MethodRouter<AppState>)> = Vec::new();
    for (method, uri, mr) in handlers {
        let s = spec(method, uri);
        let abilities = s.abilities;
        let mut mr = mr;
        if !abilities.is_empty() {
            mr = mr.route_layer(from_fn(move |req, next| {
                crate::auth::require_abilities(abilities, req, next)
            }));
        }
        mr = match s.group {
            Group::Public => mr,
            Group::Main => {
                mr.route_layer(from_fn_with_state(state.clone(), crate::auth::main_guard))
            }
            Group::Disable => mr.route_layer(from_fn_with_state(
                state.clone(),
                crate::auth::disable_guard,
            )),
        };
        match by_path.iter_mut().find(|(p, _)| *p == uri) {
            Some((_, existing)) => {
                let taken = std::mem::take(existing);
                *existing = taken.merge(mr);
            }
            None => by_path.push((uri, mr)),
        }
    }

    let mut router = Router::new();
    for (uri, mr) in by_path {
        router = router.route(&format!("/{uri}"), mr.fallback(crate::fallback::fallback));
    }
    router.fallback(crate::fallback::fallback).with_state(state)
}

fn on_get<H, T>(h: H) -> MethodRouter<AppState>
where
    H: axum::handler::Handler<T, AppState>,
    T: 'static,
{
    on(axum::routing::MethodFilter::GET, h)
}

fn on_post<H, T>(h: H) -> MethodRouter<AppState>
where
    H: axum::handler::Handler<T, AppState>,
    T: 'static,
{
    on(axum::routing::MethodFilter::POST, h)
}

#[allow(dead_code)]
fn method(m: &str) -> Method {
    m.parse().unwrap_or(Method::GET)
}
